const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(
    text(value).toLowerCase()
  );
};

const clinic_name = text(input.clinic_name);
const channel = text(input.channel || 'webchat').toLowerCase();
const external_conversation_id =
  text(input.external_conversation_id);
const mobile = text(input.mobile);
const message_type =
  text(input.message_type || 'text').toLowerCase();
const message_text = text(input.message_text);
const language =
  text(input.language || 'fa').toLowerCase();

let message_payload = input.message_payload ?? {};

try {
  if (typeof message_payload === 'string') {
    message_payload =
      JSON.parse(message_payload || '{}');
  }
} catch {
  message_payload = null;
}

const context_message_limit =
  Number(input.context_message_limit ?? 20);

const model_provider =
  text(input.model_provider || 'openai').toLowerCase();

const model_name =
  text(input.model_name || 'gpt-5-mini');

const intent_prompt_version =
  text(
    input.intent_prompt_version ||
    'intent-router-final-v5'
  );

const response_prompt_version =
  text(
    input.response_prompt_version ||
    'response-composer-final-v2'
  );

const max_retry_attempts =
  Number(input.max_retry_attempts ?? 3);

const webhook_base_url = text(
  input.webhook_base_url ||
  'http://n8n:5678/webhook'
).replace(/\/+$/, '');

const confirm_message =
  toBoolean(input.confirm_message);

const allowedChannels = [
  'whatsapp',
  'sms',
  'phone',
  'telegram',
  'webchat',
  'manual',
  'api',
];

const allowedMessageTypes = [
  'text',
  'audio',
  'image',
  'file',
  'event',
];

const allowedLanguages = [
  'fa',
  'en',
  'ar',
  'unknown',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!allowedChannels.includes(channel)) {
  errors.push({
    field: 'channel',
    message: 'کانال مکالمه معتبر نیست.',
  });
}

if (!external_conversation_id) {
  errors.push({
    field: 'external_conversation_id',
    message: 'شناسه مکالمه الزامی است.',
  });
}

if (
  mobile &&
  !/^\+?[0-9]{8,15}$/.test(mobile)
) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (!allowedMessageTypes.includes(message_type)) {
  errors.push({
    field: 'message_type',
    message: 'نوع پیام معتبر نیست.',
  });
}

if (!message_text) {
  errors.push({
    field: 'message_text',
    message:
      'متن یا متن استخراج‌شده پیام برای پردازش AI الزامی است.',
  });
}

if (message_text.length > 12000) {
  errors.push({
    field: 'message_text',
    message: 'متن پیام بیش از حد طولانی است.',
  });
}

if (
  !message_payload ||
  Array.isArray(message_payload) ||
  typeof message_payload !== 'object'
) {
  errors.push({
    field: 'message_payload',
    message: 'message_payload باید یک شیء JSON باشد.',
  });

  message_payload = {};
}

if (!allowedLanguages.includes(language)) {
  errors.push({
    field: 'language',
    message: 'زبان معتبر نیست.',
  });
}

if (
  !Number.isInteger(context_message_limit) ||
  context_message_limit < 1 ||
  context_message_limit > 100
) {
  errors.push({
    field: 'context_message_limit',
    message: 'تعداد پیام‌های Context باید بین 1 و 100 باشد.',
  });
}

if (!model_provider) {
  errors.push({
    field: 'model_provider',
    message: 'ارائه‌دهنده مدل الزامی است.',
  });
}

if (!model_name) {
  errors.push({
    field: 'model_name',
    message: 'نام مدل الزامی است.',
  });
}

if (
  !intent_prompt_version ||
  !response_prompt_version
) {
  errors.push({
    field: 'prompt_version',
    message: 'نسخه پرامپت‌ها الزامی است.',
  });
}

if (
  !Number.isInteger(max_retry_attempts) ||
  max_retry_attempts < 1 ||
  max_retry_attempts > 10
) {
  errors.push({
    field: 'max_retry_attempts',
    message: 'حداکثر تلاش Tool باید بین 1 و 10 باشد.',
  });
}

if (!/^https?:\/\/.+/i.test(webhook_base_url)) {
  errors.push({
    field: 'webhook_base_url',
    message: 'آدرس پایه Webhook معتبر نیست.',
  });
}

if (confirm_message !== true) {
  errors.push({
    field: 'confirm_message',
    message: 'پردازش پیام باید صریحاً تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    channel,
    external_conversation_id,
    mobile,
    message_type,
    message_text,
    message_payload,
    language,
    context_message_limit,
    model_provider,
    model_name,
    intent_prompt_version,
    response_prompt_version,
    max_retry_attempts,
    webhook_base_url,
    confirm_message,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

const input = $json;
const base = input.webhook_base_url;

return [{
  json: {
    ...input,
    store_message_url:
      `${base}/clinic/conversations/message`,
    analyze_message_url:
      `${base}/clinic/ai/analyze-message`,
    safety_gate_url:
      `${base}/clinic/ai/safety-gate`,
    tool_router_url:
      `${base}/clinic/ai/tool-router`,
    execute_tool_url:
      `${base}/clinic/ai/execute-routed-tool`,
    compose_response_url:
      `${base}/clinic/ai/compose-response`,
  },
}];

const stage = $json ?? {};

if (stage.success !== true) {
  const message =
    stage.message ||
    stage.result ||
    'Internal workflow stage failed.';

  throw new Error(message);
}

return [{ json: stage }];

