const config =
  $('Build Internal Workflow URLs').first().json;

return [{
  json: {
    session_id: stored.session_id,
    message_id: stored.message_id,
    context_message_limit:
      config.context_message_limit,
    model_provider:
      config.model_provider,
    model_name:
      config.model_name,
    prompt_version:
      config.intent_prompt_version,
    confirm_analysis: true,
  },
}];

