if (stage.success !== true) {
  const message =
    stage.message ||
    stage.result ||
    'Internal workflow stage failed.';

  throw new Error(message);
}

return [{ json: stage }];

const routing = $json;
const config =
  $('Build Internal Workflow URLs').first().json;

return [{
  json: {
    session_id: routing.session_id,
    message_id: routing.message_id,
    webhook_base_url:
      config.webhook_base_url,
    allow_retry: true,
    max_retry_attempts:
      config.max_retry_attempts,
    confirm_execution: true,
  },
}];

const source = $json;
const config =
  $('Build Internal Workflow URLs').first().json;

const sessionId =
  source.session_id ??
  $('Require Tool Route').first().json.session_id;

const messageId =
  source.message_id ??
  $('Require Tool Route').first().json.message_id;

return [{
  json: {
    session_id: sessionId,
    message_id: messageId,
    model_provider:
      config.model_provider,
